CREATE TABLE public.quote_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (char_length(name) BETWEEN 2 AND 120), phone text NOT NULL CHECK (phone ~ '^[0-9]{10,11}$'), address text NOT NULL DEFAULT '' CHECK (char_length(address) <= 500), service text NOT NULL CHECK (char_length(service) <= 100), details text NOT NULL DEFAULT '' CHECK (char_length(details) <= 3000), photo_path text, source text NOT NULL DEFAULT 'quote' CHECK (source IN ('quote','catalogue')), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.quote_requests TO anon;
GRANT ALL ON public.quote_requests TO service_role;
ALTER TABLE public.quote_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Visitors submit requests only" ON public.quote_requests FOR INSERT TO anon WITH CHECK (photo_path IS NULL OR photo_path ~ '^[a-f0-9-]{36}\.(jpg|png|webp)$');
CREATE INDEX quote_requests_phone_created ON public.quote_requests(phone, created_at);
CREATE FUNCTION public.limit_quote_requests() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtext(NEW.phone)); IF EXISTS (SELECT 1 FROM public.quote_requests WHERE phone = NEW.phone AND created_at > now() - interval '1 minute') THEN RAISE EXCEPTION 'Please wait before submitting again'; END IF; RETURN NEW; END $$;
CREATE TRIGGER limit_quote_requests BEFORE INSERT ON public.quote_requests FOR EACH ROW EXECUTE FUNCTION public.limit_quote_requests();